toolInput.script:
import json, requests, sys

url = "https://open.feishu.cn/open-apis/bot/v2/hook/39ace5b8-ddf6-4ccf-8912-2c2681c618a4"

card = {
    "msg_type": "interactive",
    "card": {
        "header": {
            "title": {
                "tag": "plain_text",
                "content": "✅ 澳洲冰箱新品监控日报 - 2026-06-18"
            },
            "template": "blue"
        },
        "elements": [
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "本日对以下 5 个品牌进行了例行巡检，均无新品上架或状态变更：\n\n**海信 Hisense** — 页面展示产品均在基线中，Featured Fridges 无变化\n**美的 Midea** — 15 款产品无变化，MDRS925 / MDRF923 仍为 Coming Soon\n**三星 Samsung** — 搜索未发现 2026 年新款冰箱\n**LG** — 搜索未发现 2026 年新款冰箱\n**西屋 Westinghouse** — 展示产品无变化\n\n---\n**重点关注项目状态：**\n• 美的 MDRT580MTF45AP (413L)：✅ 已确认在售（6/17 起）\n• 美的 MDRS925FIM45AP (700L)：⚠️ 仍为 Coming Soon\n• 美的 MDRF923FIM45AP (706L)：⚠️ 仍为 Coming Soon"
                }
            },
            {
                "tag": "hr"
            },
            {
                "tag": "note",
                "elements": [
                    {
                        "tag": "plain_text",
                        "content": "由 Incaier Agent 自动监控 | 下次汇总：明天下午 3:07"
                    }
                ]
            }
        ]
    }
}

resp = requests.post(url, json=card, timeout=30)
result = {"status_code": resp.status_code, "body": resp.text}
with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)
print(resp.status_code, resp.text[:200])

